def _parse_ipv4(ip_str: str) -> int:
    parts = ip_str.split(".")
    if len(parts) != 4:
        raise ValueError("IPv4 address must contain exactly 4 octets")

    val = 0
    for p in parts:
        # Check for empty string, leading '+', or non-digit characters
        if not p or not p.isdigit() or p.startswith("+"):
            raise ValueError(f"Invalid octet: {p!r}")
        num = int(p)
        if not (0 <= num <= 255):
            raise ValueError(f"Octet outside 0-255: {num}")
        val = (val << 8) | num
    return val


def cidr_contains(cidr: str, ip: str) -> bool:
    if "/" not in cidr:
        raise ValueError("CIDR notation must contain a '/'")

    parts = cidr.split("/")
    if len(parts) != 2:
        raise ValueError("CIDR notation must contain exactly one '/'")

    cidr_ip_str, prefix_str = parts
    if not prefix_str or not prefix_str.isdigit() or prefix_str.startswith("+"):
        raise ValueError(f"Invalid prefix length: {prefix_str!r}")

    prefix = int(prefix_str)
    if not (0 <= prefix <= 32):
        raise ValueError(f"Prefix length must be between 0 and 32, got {prefix}")

    cidr_int = _parse_ipv4(cidr_ip_str)
    ip_int = _parse_ipv4(ip)

    if prefix == 0:
        return True

    mask = ((1 << 32) - 1) ^ ((1 << (32 - prefix)) - 1)
    return (cidr_int & mask) == (ip_int & mask)
